insert into org.fonte_uso (circulo, fonte, uso) select circulo, fonte, uso from jsonb_to_recordset($j$[{"circulo": 1, "fonte": "apqc", "uso": "PCF 7.4. Mostra que os processos de identidade estão espalhados por estratégia (1.1.4, 1.2.1), marketing (3.2.1.2, 3.2.1.4), pessoas (7.1.1.9, 7.3.1.1, 7.5.1, 7.8) e relações externas (categoria 12.0). Não existe categoria de identidade: por isso a Identidade padroniza e os círculos donos dessas funções executam."}, {"circulo": 1, "fonte": "collins", "uso": "A visão tem duas partes: ideologia central (valores e propósito) e futuro imaginado. Base da ID-01."}, {"circulo": 1, "fonte": "iso37000", "uso": "O propósito é o primeiro dos 11 princípios de governança; os valores informam o propósito e o modo de alcançá-lo. Base da aprovação pelos sócios na ID-01."}, {"circulo": 1, "fonte": "pas808", "uso": "Guia para organizações orientadas a propósito, incluindo prestação de contas aos públicos. Base do rascunho do relato de impacto transferido à Governança."}, {"circulo": 1, "fonte": "quinn", "uso": "Oito passos; usamos “descobrir o propósito”, “estimular o aprendizado individual” e “conectar as pessoas ao propósito”. Base da ID-01 e do rascunho de propósito pessoal transferido à Gestão."}, {"circulo": 1, "fonte": "hatch", "uso": "Marca corporativa pede alinhamento entre visão, cultura e imagem; as três lacunas são visão–cultura, imagem–cultura e imagem–visão. Base da ID-05; a ID-04 usa o relatório dessas lacunas como insumo."}, {"circulo": 1, "fonte": "aaker", "uso": "Arquitetura de marca em quatro estratégias: casa de marcas (house of brands), marcas endossadas (endorsed brands), submarcas (subbrands) e casa com marca (branded house, em que a marca-mãe domina); perguntas para escolher. Base da etapa 2 da ID-03."}, {"circulo": 1, "fonte": "wheeler", "uso": "Processo em cinco fases: pesquisa, estratégia, desenho da identidade, pontos de contato e gestão dos ativos. Base da ID-03."}, {"circulo": 1, "fonte": "inpi", "uso": "O registro de marca vale 10 anos, renováveis; a prorrogação é pedida no último ano de vigência ou em até seis meses depois. Base da etapa 5 da ID-03."}, {"circulo": 1, "fonte": "iso20671", "uso": "Avaliação de marca com elementos de entrada, dimensões de saída e indicadores. Base da ID-05."}, {"circulo": 1, "fonte": "iso10010", "uso": "Orientação para entender, avaliar e melhorar a cultura de qualidade. Usamos a sequência entender, avaliar e melhorar na ID-05."}, {"circulo": 1, "fonte": "mckinsey", "uso": "Quatro alavancas para mudar comportamento: exemplo dos líderes, entendimento e convicção, desenvolvimento de habilidades e mecanismos formais. Base do kit de cultura e pessoas, na ID-02."}, {"circulo": 1, "fonte": "schein", "uso": "Cultura em três níveis: artefatos e comportamentos, valores declarados e pressupostos básicos. Tratar rituais como artefatos é leitura nossa; o verbete não fala em rituais. Base do padrão dos rituais, na ID-02."}, {"circulo": 1, "fonte": "craig", "uso": "Declaração de propósito pessoal seguida de um plano para transformar o propósito em impacto. Base do rascunho de propósito pessoal transferido à Gestão."}, {"circulo": 1, "fonte": "reptrak", "uso": "Sete fatores de reputação: produtos e serviços, desempenho, inovação, liderança, conduta, cidadania e ambiente de trabalho. Usados como temas da percepção dos públicos que a ID-05 recebe de Relações."}, {"circulo": 1, "fonte": "iso22361", "uso": "Diretrizes para a capacidade de gestão de crises. Base do protocolo de crise, que a ID-02 entrega à Governança e a Relações."}, {"circulo": 1, "fonte": "nng", "uso": "Quatro dimensões de tom: formal ou casual, sério ou divertido, respeitoso ou irreverente, sóbrio ou entusiasmado. Base do guia de voz na ID-02."}, {"circulo": 1, "fonte": "google_persona", "uso": "Passos para definir a persona de um agente de conversa. Base da persona dos agentes na ID-02."}, {"circulo": 1, "fonte": "impact", "uso": "Cinco dimensões de impacto: o quê, quem, quanto, contribuição e risco. Base da definição do que conta como impacto, que a ID-02 entrega à Governança e à Estratégia."}, {"circulo": 1, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, regra de negócio e script, além da atividade de chamada."}, {"circulo": 1, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 1, "fonte": "dmn", "uso": "Padrão de modelagem de decisões, que inclui tabelas de decisão e foi desenhado para uso ao lado do BPMN. Usado na ID-02 para os critérios de decisão e para a regra de uso da marca por terceiros."}, {"circulo": 1, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 1, "fonte": "iia", "uso": "Três linhas: a primeira está ligada à entrega de produtos e serviços; a segunda dá conhecimento especializado, apoio, monitoramento e contestação; a terceira, a auditoria interna, dá avaliação e assessoria independentes. Usado por analogia na ID-02 e na ID-05 para separar quem padroniza (Identidade), quem executa (os outros círculos) e quem audita (Governança)."}, {"circulo": 2, "fonte": "apqc", "uso": "PCF 7.4, categoria 1.0, Develop Vision and Strategy, com quatro grupos: 1.1, conceito de negócio e visão de longo prazo; 1.2, estratégia de negócio; 1.3, iniciativas estratégicas; 1.4, modelos de negócio. A tabela de cobertura, na aba Método, mostra onde cada processo foi parar: nas seis jornadas ou em outro círculo."}, {"circulo": 2, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, regra de negócio, script e recebimento, além da atividade de chamada."}, {"circulo": 2, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 2, "fonte": "dmn", "uso": "Padrão de modelagem de decisões, que inclui tabelas de decisão. Usado na ES-04 para a tabela de alçadas e para o limite de recursos da alocação."}, {"circulo": 2, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 2, "fonte": "iia", "uso": "No modelo, o órgão de governança presta contas pela supervisão da organização e delega responsabilidade e recursos à gestão; as três linhas ficam abaixo dele. Usado por analogia para separar o que os sócios aprovam (ES-01, ES-02, ES-03 e ES-05) do que a Estratégia propõe e decide dentro da alçada."}, {"circulo": 2, "fonte": "kaplan", "uso": "Sistema de gestão em cinco estágios: desenvolver a estratégia, traduzir a estratégia, planejar as operações, monitorar e aprender, testar e adaptar a estratégia. Os autores descrevem três tipos de reunião (revisão operacional, revisão da estratégia e teste e adaptação da estratégia) e pedem pautas distintas para a revisão operacional e a da estratégia, para o curto prazo não expulsar a discussão da estratégia. Base da sequência ES-01, ES-03 e ES-06. Pôr o ritual operacional na Gestão e a revisão da estratégia neste círculo é escolha nossa: os autores dizem que as mesmas pessoas costumam participar das duas reuniões."}, {"circulo": 2, "fonte": "rumelt", "uso": "O núcleo de uma boa estratégia tem três partes: diagnóstico, política orientadora e ações coerentes. Um dos sinais de estratégia ruim é confundir alvos com estratégia. Base das etapas 1 e 2 da ES-01 e da separação entre formular (ES-01) e fixar alvos (ES-03)."}, {"circulo": 2, "fonte": "okr", "uso": "Objetivos ambiciosos e resultados-chave mensuráveis. Base das etapas 1 e 2 da ES-03."}, {"circulo": 2, "fonte": "lei", "uso": "Desdobramento da estratégia (hoshin kanri): alinha as funções e atividades da organização, na vertical e na horizontal, com os objetivos estratégicos, num processo de cima para baixo e de baixo para cima. O verbete chama esse diálogo de catchball. Base da etapa 2 da ES-03."}, {"circulo": 2, "fonte": "horizons", "uso": "Três horizontes de crescimento, geridos ao mesmo tempo: o negócio principal de hoje (horizonte 1), as oportunidades emergentes (horizonte 2) e as ideias de crescimento futuro (horizonte 3). Usado para dar papel a cada unidade no portfólio-alvo (ES-01 e ES-02) e para situar as apostas (ES-04)."}, {"circulo": 2, "fonte": "parenting", "uso": "Duas perguntas que, segundo os autores, a maioria dos executivos-chefes deixa de responder na estratégia corporativa: que negócios esta empresa, e não as rivais, deve ter, e por quê; e que estrutura organizacional, processos de gestão e filosofia favorecem o desempenho superior dos seus negócios. Base do portfólio-alvo na ES-01, da leitura do portfólio na ES-02 e do caso na ES-05."}, {"circulo": 2, "fonte": "realloc", "uso": "Quatro atividades de alocação: semear (entrar em área de negócio nova, por aquisição ou investimento próprio), nutrir (reforçar um negócio existente), podar (tirar recursos de um negócio existente) e colher (vender negócios inteiros que não cabem mais no portfólio ou separá-los). Quatro recomendações: ter um portfólio-alvo, usar todos os instrumentos de realocação, adotar regras simples para romper o status quo e implantar processos que reduzam a inércia. Numa amostra de mais de 1.600 empresas dos Estados Unidos, de 1990 a 2005, os autores relatam que o terço que mais realocou capital entre unidades de negócio teve, em média, retorno total ao acionista 30% maior por ano que o terço que menos realocou: 10,2% contra 7,8% ao ano, diferença relativa, não de 30 pontos percentuais. Em períodos de menos de três anos, quem mais realocou teve retorno menor. Base da ES-02 e, na venda de empresa, da ES-05."}, {"circulo": 2, "fonte": "stagegate", "uso": "O trabalho de inovação é dividido em estágios, cada um precedido de um portão. Em cada portão, gestores seniores (os gatekeepers) decidem entre Go, Kill, Hold e Recycle. A página lista os quatro resultados sem defini-los; lê-los como avançar, encerrar, esperar e voltar para ajuste é interpretação nossa, e o resultado “segue como está”, da revisão de uma aposta, é acréscimo nosso. A fonte tem cinco estágios e cinco portões, de desenvolvimento de produto; a ES-04 usa a lógica, com dois portões."}, {"circulo": 3, "fonte": "apqc", "uso": "PCF 7.4. Os processos das funções da Inteligência estão em dez grupos de cinco categorias: 1.4, modelos de negócio; 2.1 a 2.3, desenvolvimento de produtos e serviços; 3.1 e parte do 3.2, mercados, clientes e estratégia de marketing; 8.4, gestão da informação; e 13.5 a 13.7, gestão do conhecimento, medição e análise. A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 3, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, regra de negócio, script e recebimento, além da atividade de chamada."}, {"circulo": 3, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 3, "fonte": "dmn", "uso": "Padrão de modelagem de decisões, que inclui tabelas de decisão. Usado na IN-03 para as regras de qualidade do dado."}, {"circulo": 3, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 3, "fonte": "stagegate", "uso": "Depois da descoberta e ideação, a página lista cinco estágios, cada um precedido de um portão: conceito, construir o caso de negócio, desenvolvimento, teste e validação, e lançamento. A IN-07 cobre o trabalho entre os dois portões que a Estratégia decide: a entrada na carteira e o lançamento."}, {"circulo": 3, "fonte": "odni_ciclo", "uso": "Ciclo de inteligência em seis passos: planejamento, coleta, processamento, análise, disseminação e avaliação. No planejamento, quem decide determina que temas precisam ser tratados e define as prioridades de inteligência; a avaliação dos produtos é contínua. Base da sequência de etapas da IN-01, incluída a avaliação de uso da leitura."}, {"circulo": 3, "fonte": "herring", "uso": "Processo de tópicos-chave de inteligência (KIT): as necessidades de inteligência são identificadas e priorizadas em diálogo com quem decide. O resumo informa que o artigo traz protocolos de exemplo de três tipos: decisões e ações estratégicas, temas de alerta antecipado e descrição dos principais atores do mercado. Base da etapa 1 da IN-01."}, {"circulo": 3, "fonte": "horizon", "uso": "Horizon scanning: coleta sistemática de percepções sobre tendências emergentes e sinais fracos de mudança, para identificar ameaças, riscos e oportunidades. Cinco passos: formar o grupo, identificar as fontes, reunir e guardar os dados de forma organizada, analisar e redigir os resultados. Base das etapas 2 e 3 da IN-01."}, {"circulo": 3, "fonte": "cebma", "uso": "Prática baseada em evidência: decidir com o uso consciencioso, explícito e criterioso da melhor evidência disponível, de várias fontes. A definição enumera seis habilidades: perguntar, buscar, avaliar criticamente, agregar, aplicar e avaliar o resultado da decisão. Base das quatro etapas da IN-02 e da conferência do resultado na IN-08."}, {"circulo": 3, "fonte": "yardstick", "uso": "Régua de probabilidade da inteligência de defesa britânica: a escala de probabilidade é dividida em sete faixas numéricas, com termos atribuídos a cada faixa. Usamos a ideia de termos padronizados para declarar o grau de confiança na IN-01 e na IN-02. A régua trata de probabilidade; a lista dos termos e as faixas não foram lidas."}, {"circulo": 3, "fonte": "dqf", "uso": "Seis dimensões de qualidade do dado: completude, unicidade, consistência, atualidade, validade e exatidão. Ciclo de vida em seis estágios: planejar; coletar ou adquirir, e ingerir; preparar, guardar e manter; usar e processar; compartilhar e publicar; arquivar ou destruir. Base das cinco etapas da IN-03 e da marca de qualidade dos indicadores na IN-04."}, {"circulo": 3, "fonte": "fair", "uso": "Princípios de localização (F1 a F4): identificador único e persistente, metadados ricos, metadados que citam o identificador do dado e registro em recurso pesquisável. Base da ficha e do catálogo de dados na IN-03."}, {"circulo": 3, "fonte": "lgpd", "uso": "Definições de dado pessoal, dado pessoal sensível, dado anonimizado e tratamento (art. 5º); princípios da finalidade, da adequação e da necessidade (art. 6º); término do tratamento e eliminação dos dados, com as finalidades para as quais a conservação é autorizada (arts. 15 e 16); dever de manter registro das operações de tratamento (art. 37). Base da classificação, da recusa e da retirada de dado na IN-03. Quem define a regra é a Governança."}, {"circulo": 3, "fonte": "fabric", "uso": "Seis propriedades de um sistema de informação de desempenho: focado, apropriado, equilibrado, robusto, integrado e com custo compatível. Oito critérios de uma boa medida: relevante, sem incentivo perverso, atribuível, bem definida, tempestiva, confiável, comparável e verificável. Base da ficha e da revisão dos indicadores na IN-04."}, {"circulo": 3, "fonte": "kcs", "uso": "Oito práticas em dois ciclos. No ciclo de solução: capturar, estruturar, reusar e melhorar. No ciclo de evolução: saúde do conteúdo, integração ao processo, avaliação de desempenho, e liderança e comunicação. O ciclo de evolução aprende com os padrões de reuso. Base das etapas da IN-05 e do cruzamento de lições na IN-08. O guia nasceu no atendimento (suporte ao cliente e help desk) e, na versão 6, declara aplicação além do suporte; usá-lo em bases para agentes é leitura nossa."}, {"circulo": 3, "fonte": "apqc_km", "uso": "Fluxo do conhecimento em sete passos: criar, identificar, coletar, revisar, compartilhar, acessar e usar. Base da sequência da IN-05 e da IN-06."}, {"circulo": 3, "fonte": "anthropic_evals", "uso": "Critério de sucesso específico, mensurável, alcançável e relevante; avaliações que espelham a tarefa real e são automatizadas quando possível; três formas de correção: por código, por pessoa e por modelo. Base das perguntas de teste da IN-05 e do critério de sucesso e dos casos de teste da IN-06."}, {"circulo": 3, "fonte": "nist_airmf", "uso": "O núcleo tem quatro funções: governar, mapear, medir e gerir. Medir usa ferramentas e métodos quantitativos, qualitativos ou mistos para analisar, avaliar, comparar e monitorar. Base da avaliação do método em uso por agentes, na etapa 5 da IN-06. O framework trata de risco de IA; usá-lo para a qualidade do resultado é leitura nossa."}, {"circulo": 3, "fonte": "pdca", "uso": "Ciclo de quatro passos para conduzir uma mudança: planejar, testar em pequena escala, verificar o que se aprendeu e agir, incorporando o que funcionou. Base do teste em caso real da IN-06 e da sequência da IN-08."}, {"circulo": 3, "fonte": "nng_blueprint", "uso": "Mapa de serviço com quatro elementos: ações do cliente, ações à vista do cliente, ações de bastidor e processos. Base do desenho da entrega na etapa 4 da IN-07."}, {"circulo": 3, "fonte": "bmc", "uso": "Quadro de modelo de negócio em nove blocos: segmentos de clientes, propostas de valor, canais, relacionamento com clientes, fontes de receita, recursos-chave, atividades-chave, parcerias-chave e estrutura de custos. Base da etapa 5 da IN-07."}, {"circulo": 3, "fonte": "vpc", "uso": "Perfil do cliente (tarefas, dores e ganhos) e mapa de valor (o que se oferece, as dores que alivia e os ganhos que cria). O encaixe é uma afirmação até os clientes confirmarem. Base das etapas 3 e 6 da IN-07."}, {"circulo": 3, "fonte": "leanstartup", "uso": "Construir, medir e aprender: transformar ideias em produto, medir a resposta dos clientes e aprender se é o caso de mudar o rumo ou perseverar. O produto mínimo viável serve para começar a aprender o mais cedo possível. Base do piloto na etapa 6 da IN-07."}, {"circulo": 3, "fonte": "doublediamond", "uso": "Quatro fases em dois diamantes: descobrir e definir o problema, desenvolver e entregar a solução. Base da ordem das etapas 3 e 4 da IN-07: primeiro o problema, depois a solução."}, {"circulo": 3, "fonte": "jaakkola", "uso": "Três práticas de produtização em pequenas empresas de serviços profissionais: especificar e padronizar a oferta; tornar tangíveis a oferta e a competência profissional; sistematizar e padronizar processos e métodos. Base da etapa 7 da IN-07 e da IN-06. O estudo descreve práticas relatadas por gestores; usá-las como roteiro é leitura nossa."}, {"circulo": 4, "fonte": "apqc", "uso": "PCF 7.4. Os processos das funções de Relações estão em quatro blocos: 1.2.8, estratégia de experiência do cliente; 3.2 e 3.3, estratégia e planos de marketing; 3.4.2, 3.5.1, 3.5.2 e 3.5.5, oportunidades, clientes e parceiros; 12.2 e 12.5, relações com governo, entidades e imprensa. A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 4, "fonte": "reptrak", "uso": "Sete fatores de reputação, que formam a dimensão “Think” do modelo da RepTrak: produtos e serviços, desempenho, inovação, liderança, conduta, cidadania e ambiente de trabalho. Usados como temas para agrupar os sinais e a percepção dos públicos na RE-08."}, {"circulo": 4, "fonte": "iso22361", "uso": "Diretrizes para a capacidade de gestão de crises. Base do protocolo de crise da Identidade, que a RE-08 usa para classificar o sinal e acionar o comitê da Governança. Lemos só o resumo."}, {"circulo": 4, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, regra de negócio, script e recebimento, além da atividade de chamada."}, {"circulo": 4, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 4, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 4, "fonte": "lgpd", "uso": "Bases legais do tratamento, entre elas o consentimento, a execução de contrato e o legítimo interesse (art. 7º); consentimento por escrito ou por meio que demonstre a vontade do titular, revogável a qualquer momento (art. 8º); acesso facilitado às informações do tratamento (art. 9º); direitos do titular, entre eles confirmar a existência do tratamento, acessar, corrigir, anonimizar, bloquear ou eliminar dados desnecessários ou excessivos, portar, eliminar os dados tratados com consentimento e revogar o consentimento (art. 18, I a VI e IX). Base do registro com a base legal, da saída do contato e da execução dos pedidos dos titulares na RE-03. Quem define a regra é a Governança."}, {"circulo": 4, "fonte": "nng_blueprint", "uso": "Mapa de serviço com quatro elementos: ações do cliente, ações à vista do cliente, ações de bastidor e processos. Base do desenho dos pontos de contato com Operações na etapa 2 da RE-04."}, {"circulo": 4, "fonte": "iso44001", "uso": "Norma de requisitos para identificar, desenvolver e gerir relações de negócio colaborativas dentro das organizações ou entre elas. Lemos só o resumo; a norma completa é paga e está em revisão. Usada como referência do ciclo de vida da parceria na RE-06, do encaixe à saída; as etapas da jornada vêm do APQC (3.4.2, 3.5.5 e 12.2.3)."}, {"circulo": 4, "fonte": "barcelona", "uso": "Sete princípios de medição da comunicação, de 2020. Os que usamos: fixar alvos é pré-requisito do planejamento e da medição; medir resultado e efeito, e não só a entrega; medir de forma qualitativa e quantitativa; a equivalência em valor de anúncio (AVE) não é o valor da comunicação. Base dos alvos e das medidas de cada ação na RE-01 e na RE-02, da medição do efeito de cada tema na RE-07 e da leitura da percepção na RE-08. Os princípios tratam de comunicação; usá-los também nas ações de demanda é leitura nossa."}, {"circulo": 4, "fonte": "nng_journey", "uso": "O mapa da jornada é a visualização do processo que uma pessoa percorre para atingir um objetivo. Cinco elementos: o ator, o cenário e as expectativas, as fases da jornada, as ações, os modos de pensar (mindsets) e as emoções, e as oportunidades. Base do mapa da jornada na RE-04."}, {"circulo": 5, "fonte": "apqc", "uso": "PCF 7.4. Os processos de Negócios estão em quatro grupos da categoria 3: 3.2.2 e 3.3.3, estratégia e gestão de preços, e 3.3.9, material de produto (NE-01); 3.2.3, estratégia de canais, e 3.4, estratégia de vendas, com previsão, alvos e orçamento de vendas (NE-02); e 3.5, planos de venda, com oportunidades, contas, propostas e cotações, pedidos e parceiros (NE-03 a NE-07). A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 5, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, regra de negócio, script e recebimento, além da atividade de chamada."}, {"circulo": 5, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 5, "fonte": "dmn", "uso": "Notação de regras de decisão. Base das tarefas de regra que aplicam a tabela de preços, a política comercial e as alçadas de concessão na NE-01, na NE-03, na NE-04 e na NE-06; a tabela de alçadas é da Governança."}, {"circulo": 5, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 5, "fonte": "l14133", "uso": "Fases do processo de licitação, em sequência: preparatória, divulgação do edital, apresentação de propostas e lances, quando for o caso, julgamento, habilitação, recursal e homologação (art. 17, caput); a habilitação pode vir antes das propostas e do julgamento, por ato motivado, se o edital prever (§ 1º); a forma eletrônica é a preferida (§ 2º). A NE-05 começa na divulgação do edital (art. 17, II); a fase preparatória, caracterizada pelo planejamento (art. 18, caput), não tem tarefa de Negócios, salvo responder a pedido de cotação. Sistema de registro de preços, ata de registro de preços e órgão participante e não participante (art. 6º, incisos XLV, XLVI, XLVIII e XLIX). Base das etapas da NE-05. Lidos em 03/10/2026, em transcrição secundária: esclarecimento e impugnação pedidos até três dias úteis antes da abertura, com resposta em até três dias úteis (art. 164); intenção de recorrer manifestada de imediato, recurso e contrarrazões em três dias úteis e decisão da autoridade superior em até dez dias úteis (art. 165); convocação para assinar no prazo do edital, prorrogável uma vez (art. 90). Na NE-06: a ata vale um ano, prorrogável por igual período se o preço for vantajoso (art. 84); a adesão de órgão não participante exige justificativa, preço compatível com o mercado e aceite do gerenciador e do fornecedor, até 50% dos quantitativos por órgão e, no total, até o dobro de cada item (art. 86). No desenho, os prazos seguem “nos prazos da lei e do edital”; a contratação direta não foi conferida."}, {"circulo": 6, "fonte": "apqc", "uso": "PCF 7.4. Os processos da Integração estão em duas categorias: 8.0, tecnologia da informação (arquitetura, portfólio de TI, segurança, identidade e acesso, criação e teste de soluções, implantação, controle de mudança e suporte), base da IT-06 e da IT-07; e 13.0, capacidades do negócio (processos, portfólio e projetos, mudança), base da IT-01 a IT-05 e da IT-08. A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 6, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, script e recebimento, além da atividade de chamada."}, {"circulo": 6, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 6, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 6, "fonte": "iso21502", "uso": "Norma de orientação para gestão de projetos, aplicável a qualquer organização e a qualquer tipo de projeto; não trata de programas nem de portfólios. Lemos só o resumo; a norma está publicada e marcada para revisão. Referência do ciclo de projeto (registrar, planejar, acompanhar e encerrar com lições) na IT-01, na IT-02, na IT-03 e na IT-04; o portfólio vem do APQC (13.2.1)."}, {"circulo": 6, "fonte": "iso27001", "uso": "Norma de requisitos para o sistema de gestão da segurança da informação. Lemos só o resumo. Referência da operação segura da IT-07: acesso pela classificação, mudança testada e reversível e incidente de segurança tratado com a Governança, que define a política."}, {"circulo": 6, "fonte": "anthropic_evals", "uso": "Critério de sucesso específico e mensurável; avaliações que espelham a tarefa real e são automatizadas quando possível; correção por código, por pessoa e por modelo. Base dos casos de teste, do julgamento dos casos de fronteira e do critério de liberação na IT-06."}, {"circulo": 6, "fonte": "nist_airmf", "uso": "O núcleo tem quatro funções: governar, mapear, medir e gerir. Base do monitoramento em uso e da suspensão do agente que sai da alçada na IT-06. O framework trata de risco de IA; usá-lo para a operação do agente é leitura nossa."}, {"circulo": 7, "fonte": "apqc", "uso": "PCF 7.4. Os processos de Operações estão em três categorias: 4.0, cadeia de suprimentos de produtos físicos (demanda, materiais, produção, teste, armazém e transporte), base da OP-06; 5.0, entrega de serviços (governança da entrega, recursos, início, execução e conclusão), base da OP-01, da OP-02 e da OP-08; e 6.0, atendimento ao cliente (estratégia, contatos, reclamações, devoluções, pós-venda, recall e avaliação), base da OP-03, da OP-04, da OP-05 e da OP-07. A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 7, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, serviço e script; a tarefa de outro círculo ou papel aparece como tarefa simples."}, {"circulo": 7, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 7, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 7, "fonte": "l14133", "uso": "Na OP-02, contrato público: o objeto é recebido provisoriamente pelo fiscal e definitivamente por servidor ou comissão, com termo detalhado, e pode ser rejeitado no todo ou em parte (art. 140). A OP-02 trata os dois recebimentos como aceite do cliente."}, {"circulo": 7, "fonte": "cc2002", "uso": "Na OP-07, quando o cliente é empresa e não consumidor: a coisa com vício oculto pode ser enjeitada (art. 441) ou ter o preço abatido (art. 442); o prazo para isso é de trinta dias para coisa móvel, contado da entrega, e, se o vício só puder ser conhecido mais tarde, conta da ciência, até cento e oitenta dias (art. 445); na garantia contratual os prazos não correm, mas o defeito deve ser denunciado em trinta dias da descoberta (art. 446). O contrato entre empresas presume-se paritário e a alocação de riscos combinada é respeitada (art. 421-A)."}, {"circulo": 7, "fonte": "iso9001", "uso": "Norma de requisitos para o sistema de gestão da qualidade; a página oficial apresenta a edição de 2026 como a vigente e a de 2015 como retirada. Lemos só a página. Referência geral da OP-05: padrão definido, medida, não conformidade, causa, ação corretiva e efeito conferido. Não usamos nenhum requisito numerado da norma."}, {"circulo": 7, "fonte": "iso10002", "uso": "Diretrizes para o tratamento de reclamações em organizações, do planejamento à melhoria. Lemos só o resumo. Referência da OP-04: registrar, confirmar o recebimento, classificar, investigar, responder e tratar a causa."}, {"circulo": 7, "fonte": "cdc", "uso": "Código de Defesa do Consumidor, quando o cliente é consumidor. Na OP-04 e na OP-07: o fornecedor responde pelos vícios de qualidade do produto (art. 18) e do serviço (art. 20); não sanado o vício do produto no prazo máximo de trinta dias, o consumidor escolhe a troca, a devolução do valor ou o abatimento (art. 18, § 1º); nesse caso, o consumidor pode usar essas alternativas de imediato quando a troca das partes comprometer o produto ou ele for essencial (art. 18, § 3º); no serviço, escolhe a reexecução, a devolução do valor ou o abatimento (art. 20); o prazo para reclamar de vício aparente é de trinta dias para serviço e produto não duráveis e de noventa dias para serviço e produto duráveis (art. 26, I e II), contado da entrega ou do fim do serviço (art. 26, § 1º) e, no vício oculto, de quando o defeito aparece (art. 26, § 3º); a reclamação obsta a decadência até a resposta negativa, que deve ser transmitida de forma inequívoca (art. 26, § 2º, I), por isso a OP-04 responde por escrito. Na OP-07: quem descobre a periculosidade depois da venda comunica imediatamente as autoridades e os consumidores (art. 10, § 1º), antes e independentemente da decisão de recall."}, {"circulo": 7, "fonte": "lgpd", "uso": "Na OP-08: o término do tratamento e a eliminação dos dados pessoais do cliente no fim do contrato (arts. 15 e 16), conforme as regras de sigilo da Governança."}, {"circulo": 8, "fonte": "apqc", "uso": "PCF 7.4. Os processos da Gestão estão em três categorias e num grupo: 7.0, capital humano (planejamento, recrutamento, integração, desempenho, desenvolvimento, recompensa, desligamento, informação e comunicação com as pessoas), base da GE-07 a GE-11 e da GE-13; 9.0, recursos financeiros (planejamento e orçamento, receita, contabilidade, folha, contas a pagar, tesouraria e impostos), base da GE-01, da GE-03 a GE-06 e da GE-13; 10.0, ativos (planejar e adquirir, manter e baixar), base da GE-12; e o grupo 4.2, compra de materiais e serviços, base da GE-04. O grupo 9.8, controles internos, fica com a Governança. A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 8, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, serviço, script e recebimento; a tarefa de outro círculo ou papel aparece como tarefa simples."}, {"circulo": 8, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 8, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 8, "fonte": "cc2002", "uso": "Na GE-05: cada empresa segue um sistema de contabilidade com escrituração uniforme e levanta todo ano o balanço patrimonial e o de resultado (art. 1.179), com o livro Diário (art. 1.180), e guarda a escrituração enquanto não houver prescrição ou decadência (art. 1.194)."}, {"circulo": 8, "fonte": "clt", "uso": "Na GE-13: o salário mensal é pago até o quinto dia útil do mês seguinte (art. 459, § 1º); as férias, até dois dias antes do início (art. 145); acima de vinte trabalhadores no estabelecimento, o registro de entrada e saída é obrigatório, e o ponto por exceção é permitido por acordo (art. 74, §§ 2º e 4º). Na GE-07: no desligamento, as verbas rescisórias e os documentos são entregues em até dez dias do término do contrato (art. 477, § 6º)."}, {"circulo": 8, "fonte": "fgts", "uso": "Na GE-13: o depósito do FGTS é feito até o vigésimo dia de cada mês (art. 15, na redação da Lei 14.438/2022, com a arrecadação digital)."}, {"circulo": 8, "fonte": "lgpd", "uso": "Na GE-07 e na GE-09 (e também na GE-08, na GE-10 e na GE-13, que usam dados de pessoas): os dados de candidatos e de pessoas são dados pessoais, tratados com finalidade, adequação e necessidade (art. 6º, I a III) e pelas regras de sigilo da Governança. Na GE-07, a triagem feita pelo agente é revista por pessoa antes de recusar candidatos, porque o titular pode pedir a revisão de decisão tomada só por tratamento automatizado (art. 20, caput). Na GE-09, a pesquisa de cultura é analisada sem identificar quem respondeu."}, {"circulo": 9, "fonte": "apqc", "uso": "PCF 7.4. Os processos da Governança estão na categoria 11.0 (risco, conformidade, remediação e resiliência), base da GO-03, da GO-04, da GO-06 (auditoria interna, 11.2.1.3), da GO-07 e da GO-09; nos grupos 12.3 (relação com o conselho, aqui os sócios) e 12.4 (questões legais e éticas), base da GO-01, da GO-02, da GO-04 e da GO-05; no grupo 9.8 (controles internos), base da GO-03; e no elemento 13.9.2.3 (relato de sustentabilidade), base da GO-10. O PCF não tem elemento próprio de comitê de crise: a GO-08 usa o 11.4.5 (compartilhar o conhecimento de riscos) nas lições. A tabela de cobertura, na aba Método, mostra onde cada um foi parar."}, {"circulo": 9, "fonte": "bpmn", "uso": "Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, serviço e script; a tarefa de outro círculo ou papel aparece como tarefa simples."}, {"circulo": 9, "fonte": "camunda", "uso": "Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema."}, {"circulo": 9, "fonte": "sipoc", "uso": "Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa."}, {"circulo": 9, "fonte": "anpd15", "uso": "Na GO-09: o incidente que pode acarretar risco ou dano relevante é o que pode afetar significativamente interesses e direitos fundamentais dos titulares e, ao mesmo tempo, envolve ao menos um destes critérios: dados sensíveis; de crianças, adolescentes ou idosos; financeiros; de autenticação; protegidos por sigilo; ou em larga escala (art. 5º). A comunicação à autoridade e ao titular é feita em três dias úteis contados do conhecimento de que o incidente afetou dados pessoais (arts. 6º e 9º); o agente de pequeno porte conta os prazos em dobro (art. 6º, § 8º, e art. 9º, § 6º); as informações podem ser complementadas em vinte dias úteis (art. 6º, § 3º); o registro do incidente, comunicado ou não, é guardado por no mínimo cinco anos (art. 10)."}, {"circulo": 9, "fonte": "cc2002", "uso": "Na GO-05: contratos civis e empresariais presumem-se paritários e simétricos; a alocação de riscos definida pelas partes deve ser respeitada; a revisão contratual é excepcional e limitada (art. 421-A); os contratantes guardam probidade e boa-fé (art. 422). Base da revisão de cláusula fora do modelo e do risco do contrato."}, {"circulo": 9, "fonte": "lgpd", "uso": "Na GO-01: as regras de sigilo e de dados pessoais seguem os princípios de finalidade, adequação e necessidade (art. 6º, I a III), e as de guarda e eliminação seguem o término do tratamento e a eliminação dos dados (arts. 15 e 16). Na GO-07: o titular tem direito a obter do controlador o que a lei lista (art. 18); a declaração completa sobre os dados é fornecida em até quinze dias do requerimento (art. 19, II); o controlador indica o encarregado (art. 41), que aceita reclamações e comunicações dos titulares e recebe as da autoridade nacional (art. 41, § 2º, I e II); aqui, o papel de encarregado fica na Governança. Na GO-09: o incidente de segurança que possa acarretar risco ou dano relevante aos titulares é comunicado à autoridade nacional e ao titular (art. 48)."}]$j$::jsonb) as x(circulo smallint, fonte text, uso text);
